import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, shareReplay } from 'rxjs';
import type { Feature, FeatureCollection, MultiPolygon } from 'geojson';

export interface CountryShapeProperties {
  /** ISO 3166-1 alpha-2 code, uppercase; null for disputed areas without one. */
  code: string | null;
  /** [longitude, latitude] to place the country name at. */
  label: [number, number];
}

export type CountryShape = Feature<MultiPolygon, CountryShapeProperties>;

/** Static asset generated by `npm run build:map` (scripts/build-map.mjs). */
export const MAP_URL = 'maps/europe.json';

/** Country shapes for the trip map, fetched once and only when the map is first shown. */
@Injectable({ providedIn: 'root' })
export class MapDataService {
  private http = inject(HttpClient);
  private shapes$?: Observable<FeatureCollection<MultiPolygon, CountryShapeProperties>>;

  getCountryShapes(): Observable<FeatureCollection<MultiPolygon, CountryShapeProperties>> {
    this.shapes$ ??= this.http
      .get<FeatureCollection<MultiPolygon, CountryShapeProperties>>(MAP_URL)
      // shareReplay drops a failed request, so the next call retries.
      .pipe(shareReplay(1));
    return this.shapes$;
  }
}
